(function(root){
 'use strict';
 const finite=v=>typeof v==='number'&&Number.isFinite(v);
 const et=t=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(t));
 function session(t){const p=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(t));const d=Object.fromEntries(p.map(x=>[x.type,x.value]));return {day:`${d.year}-${d.month}-${d.day}`,minute:Number(d.hour)*60+Number(d.minute)};}
 function regular(b){return b.filter(x=>{const m=session(x.timestamp).minute;return m>=570&&m<960;}).sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));}
 function ema(values,n){let value=0;return values.map((v,i)=>{if(i<n){value+=v;return i===n-1?value/n:null;}value=i===n?value/n:value;value=v*2/(n+1)+value*(1-2/(n+1));return value;});}
 function wilder(values,n){let avg=0;return values.map((v,i)=>{if(i<n){avg+=v;return i===n-1?avg/n:null;}avg=i===n?avg/n:avg;avg=(avg*(n-1)+v)/n;return avg;});}
 function indicators(b){const c=b.map(x=>x.close),fast=ema(c,9),slow=ema(c,21);const tr=b.map((x,i)=>i?Math.max(x.high-x.low,Math.abs(x.high-c[i-1]),Math.abs(x.low-c[i-1])):x.high-x.low);const atr=wilder(tr,14);const gain=wilder(c.slice(1).map((x,i)=>Math.max(0,x-c[i])),14),loss=wilder(c.slice(1).map((x,i)=>Math.max(0,c[i]-x)),14);const rsi=[null,...gain.map((g,i)=>g===null?null:loss[i]===0?(g===0?50:100):100-100/(1+g/loss[i]))];let day='',sum=0,vol=0;const vwap=b.map(x=>{const d=session(x.timestamp).day;if(d!==day){day=d;sum=0;vol=0;}sum+=(finite(x.vwap)?x.vwap:(x.high+x.low+x.close)/3)*x.volume;vol+=x.volume;return vol>0?sum/vol:null;});return {fast,slow,atr,rsi,vwap};}
 function levels(b){if(b.length<22)return null;const i=indicators(b),last=b.length-1,atr=i.atr[last],prior=b.slice(-6,-1);if(!finite(atr)||atr<=0)return null;const high=Math.max(...prior.map(x=>x.high)),low=Math.min(...prior.map(x=>x.low));const day=session(b[last].timestamp).day,opening=b.find(x=>session(x.timestamp).day===day&&session(x.timestamp).minute===570);return {high,low,atr,longStop:high-1.5*atr,longTarget:high+2*atr,shortStop:low+1.5*atr,shortTarget:low-2*atr,orbHigh:opening?.high??null,orbLow:opening?.low??null,bias:i.fast[last]>i.slow[last]?'Bullish':i.fast[last]<i.slow[last]?'Bearish':'Neutral',rsi:i.rsi[last],vwap:i.vwap[last]};}
 function sizeOption({capital,riskPct,budget,buyingPower,ask,multiplier=100}){if(![capital,riskPct,budget,ask,multiplier].every(finite)||capital<0||riskPct<=0||riskPct>100||budget<0||ask<=0||multiplier<=0)return 0;const cap=Math.min(capital*riskPct/100,budget,finite(buyingPower)?Math.max(0,buyingPower):capital);return Math.max(0,Math.floor((cap+1e-9)/(ask*multiplier)));}
 function validate(s){if(!s||s.schemaVersion!==1||!s.bars||typeof s.bars!=='object'||Array.isArray(s.bars)||!Number.isFinite(Date.parse(s.capturedAt)))throw Error('Expected a version 1 Trade Desk snapshot with bars and capturedAt.');if(Object.keys(s.bars).length>100)throw Error('Too many symbols.');for(const [symbol,bars] of Object.entries(s.bars)){if(!/^[A-Z][A-Z0-9.\-]{0,14}$/.test(symbol)||!Array.isArray(bars)||bars.length>20000)throw Error('Invalid symbol or bar count.');let last=-Infinity;for(const b of bars){const t=Date.parse(b.timestamp);if(!finite(t)||t<=last||![b.open,b.high,b.low,b.close,b.volume].every(finite)||b.low<=0||b.high<Math.max(b.open,b.close)||b.low>Math.min(b.open,b.close)||b.volume<0)throw Error('Invalid or unsorted OHLCV bars.');last=t;}}if(!Array.isArray(s.contracts)||!Array.isArray(s.fills))throw Error('contracts and fills must be arrays.');for(const c of s.contracts){if(!/^[A-Z]+\d{6}[CP]\d{8}$/.test(c.symbol)||!['call','put'].includes(c.type)||!finite(c.strike)||!finite(c.multiplier)||c.multiplier<=0||!/^\d{4}-\d{2}-\d{2}$/.test(c.expiry)||!Number.isFinite(Date.parse(c.expiry))||![c.bid,c.ask].every(v=>v===null||(finite(v)&&v>=0)))throw Error('Invalid option contract.');}for(const f of s.fills){if(!['stock','option'].includes(f.asset)||!['buy','sell'].includes(f.side)||!finite(f.price)||!finite(f.quantity)||f.price<=0||f.quantity<=0||!Number.isFinite(Date.parse(f.time)))throw Error('Invalid fill.');}return s;}
 const api={session,regular,indicators,levels,sizeOption,validate,et};if(typeof module!=='undefined')module.exports=api;else root.TradeEngine=api;
})(typeof globalThis!=='undefined'?globalThis:this);
